{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    nodes = case.get("nodes")
    core_distance = case.get("core_distance")
    distances = case.get("distances")

    if not isinstance(nodes, list) or not nodes:
        raise ValueError("nodes must be a non-empty list")
    if any(not isinstance(node, str) or not node for node in nodes):
        raise ValueError("node identifiers must be non-empty strings")
    if len(set(nodes)) != len(nodes):
        raise ValueError("node identifiers must be unique")
    if not isinstance(core_distance, dict):
        raise ValueError("core_distance must be an object")
    if set(core_distance) != set(nodes):
        raise ValueError("core_distance must contain exactly the registered nodes")
    if not isinstance(distances, list):
        raise ValueError("distances must be a list")

    def valid_number(value):
        return (isinstance(value, (int, float)) and
                not isinstance(value, bool) and
                math.isfinite(value) and value >= 0)

    cores = {}
    for node in nodes:
        value = core_distance[node]
        if not valid_number(value):
            raise ValueError("core distances must be finite non-negative numbers")
        cores[node] = value

    node_set = set(nodes)
    seen_pairs = set()
    reachability_edges = []
    for entry in distances:
        if not isinstance(entry, (list, tuple)) or len(entry) != 3:
            raise ValueError("each distance must contain two endpoints and a value")
        left, right, distance = entry
        if left not in node_set or right not in node_set:
            raise ValueError("distance endpoint is not a registered node")
        if left == right:
            raise ValueError("self-distances are not valid edges")
        if not valid_number(distance):
            raise ValueError("distances must be finite non-negative numbers")
        if right < left:
            left, right = right, left
        pair = (left, right)
        if pair in seen_pairs:
            raise ValueError("duplicate undirected distance edge")
        seen_pairs.add(pair)
        weight = max(cores[left], cores[right], distance)
        reachability_edges.append([left, right, weight])

    reachability_edges.sort(key=lambda edge: (edge[2], edge[0], edge[1]))

    parent = {node: node for node in nodes}
    size = {node: 1 for node in nodes}

    def find(node):
        root = node
        while parent[root] != root:
            root = parent[root]
        while parent[node] != node:
            next_node = parent[node]
            parent[node] = root
            node = next_node
        return root

    mst_edges = []
    for left, right, weight in reachability_edges:
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            continue
        if size[root_left] < size[root_right] or (size[root_left] == size[root_right] and root_right < root_left):
            root_left, root_right = root_right, root_left
        parent[root_right] = root_left
        size[root_left] += size[root_right]
        mst_edges.append([left, right, weight])
        if len(mst_edges) == len(nodes) - 1:
            break

    if len(mst_edges) != len(nodes) - 1:
        raise ValueError("distance graph is disconnected")

    return {
        "core_distance": cores,
        "mutual_reachability_edges": reachability_edges,
        "mst_edges": mst_edges,
        "total_weight": sum(edge[2] for edge in mst_edges),
    }
"}
